def write_gbm_evaluation(store: GbmModelStore, model_id: str, evaluation: dict[str, dict[str, list[Any]]]) -> None:
    selects: list[str] = []
    for dataset_name, metrics in evaluation.items():
        for metric_name, values in metrics.items():
            for iteration, value in enumerate(values, start=1):
                value_sql = "NULL" if value is None else str(float(value))
                selects.append(
                    f"SELECT {sql_literal(str(dataset_name))} AS dataset, {sql_literal(str(metric_name))} AS metric, "
                    f"{iteration} AS iteration, {value_sql} AS value"
                )
    if not selects:
        return
    con = duckdb.connect(database=":memory:")
    try:
        con.execute(
            f"""
COPY (
  {" UNION ALL ".join(selects)}
) TO {sql_literal(str(store.artifact_path(model_id, "evaluation")))} (FORMAT PARQUET)
"""
        )
    finally:
        con.close()


def sql_scalar(value: Any) -> str:
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, (int, float)):
        number = float(value)
        return str(value) if math.isfinite(number) else "NULL"
    return sql_literal(str(value))


def write_gbm_feature_config(store: GbmModelStore, model_id: str, rows: list[dict[str, Any]]) -> None:
    store.write_json(store.artifact_path(model_id, "features"), [str(row["name"]) for row in rows])
    columns = ["name", "kind", "include", "monotonicity", "monotonicity_value", "gain", "mean_abs_shap"]
    selects = [
        "SELECT " + ", ".join(f"{sql_scalar(row.get(column))} AS {quote_ident(column)}" for column in columns)
        for row in rows
    ]
    if not selects:
        return
    con = duckdb.connect(database=":memory:")
    try:
        con.execute(
            f"""
COPY (
  {" UNION ALL ".join(selects)}
) TO {sql_literal(str(store.artifact_path(model_id, "feature_config")))} (FORMAT PARQUET)
"""
        )
    finally:
        con.close()


class BrowserSmokeTests(unittest.TestCase):
    def assert_model_command_button_styles(self, page: Any, prefix: str) -> None:
        def capture() -> dict[str, Any]:
            return page.evaluate(
                """
                (prefix) => {
                  function resolvedTokenColor(token) {
                    const probe = document.createElement("span");
                    probe.style.color = `var(${token})`;
                    document.body.append(probe);
                    const color = getComputedStyle(probe).color;
                    probe.remove();
                    return color;
                  }
                  function buttonState(name) {
                    const button = document.querySelector(`#${prefix}${name}ModelBtn`);
                    const style = getComputedStyle(button);
                    return {
                      background: style.backgroundColor,
                      borderWidth: style.borderTopWidth,
                      color: style.color,
                      height: button.getBoundingClientRect().height,
                      marginInlineStart: style.marginInlineStart,
                      outlineColor: style.outlineColor,
                      outlineStyle: style.outlineStyle,
                      outlineWidth: style.outlineWidth,
                      shared: button.classList.contains("app-control-button"),
                      command: button.classList.contains("app-command-button"),
                      danger: button.classList.contains("app-command-button--danger"),
                      oldTab: button.classList.contains("tab"),
                      oldDanger: button.classList.contains("danger-action"),
                    };
                  }
                  const transparentProbe = document.createElement("span");
                  transparentProbe.style.background = "transparent";
                  document.body.append(transparentProbe);
                  const transparent = getComputedStyle(transparentProbe).backgroundColor;
                  transparentProbe.remove();
                  return {
                    transparent,
                    muted: resolvedTokenColor("--muted"),
                    accent: resolvedTokenColor("--accent"),
                    danger: resolvedTokenColor("--danger"),
                    rename: buttonState("Rename"),
                    activate: buttonState("Activate"),
                    deleteButton: buttonState("Delete"),
                  };
                }
                """,
                prefix,
            )

        was_dark = page.evaluate("() => document.body.classList.contains('dark')")
        page.evaluate("() => document.body.classList.remove('dark')")
        page.evaluate("() => document.activeElement?.blur()")
        page.mouse.move(0, 0)
        light = capture()
        for name in ("rename", "activate", "deleteButton"):
            state = light[name]
            self.assertTrue(state["shared"])
            self.assertTrue(state["command"])
            self.assertFalse(state["oldTab"])
            self.assertFalse(state["oldDanger"])
            self.assertEqual(state["background"], light["transparent"])
            self.assertEqual(state["borderWidth"], "0px")
            self.assertEqual(state["height"], 28)
        self.assertEqual(light["rename"]["color"], light["muted"])
        self.assertEqual(light["activate"]["color"], light["muted"])
        self.assertFalse(light["rename"]["danger"])
        self.assertFalse(light["activate"]["danger"])
        self.assertTrue(light["deleteButton"]["danger"])
        self.assertEqual(light["deleteButton"]["color"], light["danger"])
        self.assertEqual(light["deleteButton"]["marginInlineStart"], "4px")

        page.locator(f"#{prefix}RenameModelBtn").hover()
        rename_hover = capture()
        self.assertEqual(rename_hover["rename"]["color"], rename_hover["accent"])
        self.assertNotEqual(rename_hover["rename"]["background"], rename_hover["transparent"])
        page.mouse.move(0, 0)
        page.locator(f"#{prefix}RenameModelBtn").focus()
        page.keyboard.press("Tab")
        rename_focus = capture()
        self.assertEqual(rename_focus["activate"]["color"], rename_focus["accent"])
        self.assertNotEqual(rename_focus["activate"]["background"], rename_focus["transparent"])
        self.assertEqual(rename_focus["activate"]["outlineStyle"], "solid")
        self.assertEqual(rename_focus["activate"]["outlineWidth"], "2px")

        page.locator(f"#{prefix}DeleteModelBtn").hover()
        delete_hover = capture()
        self.assertEqual(delete_hover["deleteButton"]["color"], delete_hover["danger"])
        self.assertNotEqual(delete_hover["deleteButton"]["background"], delete_hover["transparent"])
        page.mouse.move(0, 0)
        page.locator(f"#{prefix}ActivateModelBtn").focus()
        page.keyboard.press("Tab")
        delete_focus = capture()
        self.assertEqual(delete_focus["deleteButton"]["color"], delete_focus["danger"])
        self.assertNotEqual(delete_focus["deleteButton"]["background"], delete_focus["transparent"])
        self.assertEqual(delete_focus["deleteButton"]["outlineStyle"], "solid")
        self.assertEqual(delete_focus["deleteButton"]["outlineWidth"], "2px")

        page.evaluate("() => { document.activeElement?.blur(); document.body.classList.add('dark'); }")
        page.mouse.move(0, 0)
        dark = capture()
        self.assertEqual(dark["rename"]["background"], dark["transparent"])
        self.assertEqual(dark["rename"]["borderWidth"], "0px")
        self.assertEqual(dark["rename"]["color"], dark["muted"])
        self.assertEqual(dark["deleteButton"]["background"], dark["transparent"])
        self.assertEqual(dark["deleteButton"]["borderWidth"], "0px")
        self.assertEqual(dark["deleteButton"]["color"], dark["danger"])
        page.evaluate(
            "(wasDark) => document.body.classList.toggle('dark', wasDark)",
            was_dark,
        )

    def click_sidebar_favourite_action(self, page: Any, selector: str) -> None:
        if page.locator("#favouritesCollapseBtn").get_attribute("aria-expanded") != "true":
            page.locator("#favouritesCollapseBtn").click()
            page.wait_for_function(
                '() => document.querySelector("#favouritesCollapseBtn")?.getAttribute("aria-expanded") === "true"',
                timeout=10_000,
            )
        page.locator(".sidebar-favourites-header-row").hover()
        page.wait_for_function(
            """
            (selector) => {
              const button = document.querySelector(selector);
              const controls = button?.closest(".sidebar-favourites-controls");
              const header = document.querySelector("#favouritesCollapseBtn");
              if (!controls) return false;
              const style = getComputedStyle(controls);
              return style.display !== "none"
                && style.pointerEvents !== "none"
                && getComputedStyle(button).color === getComputedStyle(header).color;
            }
            """,
            arg=selector,
            timeout=10_000,
        )
        page.locator(selector).click()

    def assert_tool_button_tooltip_right_of_icon(self, page: Any, selector: str, text: str) -> None:
        page.locator(selector).hover()
        page.wait_for_timeout(250)
        self.assertTrue(
            page.evaluate(
                """
                () => {
                  const tooltip = document.querySelector("#toolButtonTooltip");
                  return !tooltip || tooltip.hidden;
                }
                """
            )
        )
        page.wait_for_function(
            """
            ({ selector, text }) => {
              const button = document.querySelector(selector);
              const tooltip = document.querySelector("#toolButtonTooltip");
              if (!button || !tooltip || tooltip.hidden || tooltip.textContent.trim() !== text) return false;
              const iconRect = button.querySelector(".tool-icon")?.getBoundingClientRect();
              const tooltipRect = tooltip.getBoundingClientRect();
              const front = document.elementFromPoint(
                tooltipRect.left + tooltipRect.width / 2,
                tooltipRect.top + tooltipRect.height / 2,
              );
              return tooltipRect.width > 0
                && tooltipRect.height > 0
                && iconRect
                && tooltipRect.left >= iconRect.right
                && Math.abs((tooltipRect.top + tooltipRect.height / 2) - (iconRect.top + iconRect.height / 2)) <= 2
                && (front === tooltip || tooltip.contains(front));
            }
            """,
            arg={"selector": selector, "text": text},
            timeout=2_000,
        )
        self.assertIsNone(page.locator(selector).get_attribute("title"))
        page.mouse.move(640, 400)
        page.wait_for_function(
            '() => document.querySelector("#toolButtonTooltip")?.hidden !== false',
            timeout=2_000,
        )

    def assert_tool_button_tooltip_fronts_map(self, page: Any, selector: str, text: str) -> None:
        page.locator(selector).hover()
        page.wait_for_timeout(250)
        self.assertTrue(
            page.evaluate(
                """
                () => {
                  const tooltip = document.querySelector("#toolButtonTooltip");
                  return !tooltip || tooltip.hidden;
                }
                """
            )
        )
        page.wait_for_function(
            """
            ({ selector, text }) => {
              const button = document.querySelector(selector);
              const tooltip = document.querySelector("#toolButtonTooltip");
              const map = document.querySelector("#ukMap");
              if (!button || !tooltip || !map || tooltip.hidden || tooltip.textContent.trim() !== text) return false;
              const iconRect = button.querySelector(".tool-icon")?.getBoundingClientRect();
              const tooltipRect = tooltip.getBoundingClientRect();
              const mapRect = map.getBoundingClientRect();
              const x = Math.max(mapRect.left + 2, Math.min(tooltipRect.right - 2, tooltipRect.left + tooltipRect.width / 2));
              const y = tooltipRect.top + tooltipRect.height / 2;
              if (x <= tooltipRect.left || x >= tooltipRect.right || y <= mapRect.top || y >= mapRect.bottom) return false;
              const front = document.elementFromPoint(x, y);
              return tooltipRect.width > 0
                && tooltipRect.height > 0
                && iconRect
                && tooltipRect.left >= iconRect.right
                && Math.abs((tooltipRect.top + tooltipRect.height / 2) - (iconRect.top + iconRect.height / 2)) <= 2
                && (front === tooltip || tooltip.contains(front));
            }
            """,
            arg={"selector": selector, "text": text},
            timeout=2_000,
        )
        self.assertIsNone(page.locator(selector).get_attribute("title"))
        page.mouse.move(640, 400)
        page.wait_for_function(
            '() => document.querySelector("#toolButtonTooltip")?.hidden !== false',
            timeout=2_000,
        )

    @unittest.skipUnless(RUN_BROWSER_TESTS, "set PY_LUCIDUM_RUN_BROWSER_TESTS=1 to run browser smoke tests")
    @unittest.skipUnless(sync_playwright is not None, "playwright is not installed")
    def test_monitor_shows_correlated_model_operation_and_copies_sanitized_diagnostics(self) -> None:
        with TemporaryDirectory() as tmp_dir:
            data_path = Path(tmp_dir) / "monitor.csv"
            data_path.write_text(
                "actualNumerator,Age,SAMPLE\n"
                "10,30,training\n"
                "20,40,test\n",
                encoding="utf-8",
            )
            base_url, server, thread = self.start_app(
                data_path,
                tools=["line_bar", "gbm"],
                defaults={"x": "Age", "actual": "actualNumerator", "denominator": "__none__"},
            )
            try:
                assert sync_playwright is not None
                with sync_playwright() as playwright:
                    browser = playwright.chromium.launch()
                    page = browser.new_page(viewport={"width": 1440, "height": 900})
                    page_errors: list[str] = []
                    page.on("pageerror", lambda error: page_errors.append(str(error)))
                    page.goto(f"{base_url}/monitor", wait_until="domcontentloaded")
                    page.evaluate("() => fetch('/api/schema').then((response) => response.json())")
                    page.wait_for_function(
                        """
                        () => {
                          const text = document.querySelector("#environmentMeta")?.textContent || "";
                          return text.includes("Python") && text.includes("rows");
                        }
                        """,
                        timeout=10_000,
                    )
                    validation = page.evaluate(
                        """
                        async () => {
                          const response = await fetch("/api/gbm/validate", {
                            method: "POST",
                            headers: {
                              "Content-Type": "application/json",
                              "x-lucidum-operation-id": "gbm-monitor-smoke",
                            },
                            body: JSON.stringify({ features: [], parameters: [] }),
                          });
                          return { status: response.status, body: await response.json() };
                        }
                        """
                    )
                    self.assertEqual(validation["status"], 200)
                    self.assertFalse(validation["body"]["ok"])
                    page.wait_for_function(
                        """
                        () => {
                          const row = document.querySelector('#operationsBody [data-operation-id="gbm-monitor-smoke"]');
                          return row?.textContent.includes("failed");
                        }
                        """,
                        timeout=10_000,
                    )
                    timeline_text = page.locator("#operationTimelineBody").inner_text()
                    self.assertIn("Preflight validation", timeline_text)
                    self.assertIn("Validating request", timeline_text)
                    self.assertFalse(page.locator("#operationDetailEmpty").is_visible())
                    self.assertTrue(page.locator("#operationDetailContent").is_visible())
                    self.assertIn("Python", page.locator("#environmentMeta").inner_text())
                    self.assertIn("rows", page.locator("#environmentMeta").inner_text())
                    self.assertTrue(page.locator("#copyDiagnosticsBtn").is_enabled())
                    page.evaluate(
                        """
                        () => {
                          window.__lucidumCopiedDiagnostics = "";
                          Object.defineProperty(navigator, "clipboard", {
                            configurable: true,
                            value: {
                              writeText: async (text) => {
                                window.__lucidumCopiedDiagnostics = text;
                              },
                            },
                          });
                        }
                        """
                    )
                    page.locator("#copyDiagnosticsBtn").click()
                    page.wait_for_function('() => Boolean(window.__lucidumCopiedDiagnostics)')
                    diagnostics = json.loads(page.evaluate("() => window.__lucidumCopiedDiagnostics"))
                    self.assertEqual(diagnostics["operation"]["operation_id"], "gbm-monitor-smoke")
                    self.assertEqual(diagnostics["operation"]["status"], "failed")
                    self.assertEqual(diagnostics["environment"]["dataset"]["name"], "monitor.csv")
                    self.assertNotIn(tmp_dir, json.dumps(diagnostics))
                    self.assertEqual(page_errors, [])
                    browser.close()
            finally:
                server.should_exit = True
                thread.join(timeout=5)

