                def train_route(route: Any) -> None:
                    train_payload["value"] = json.loads(route.request.post_data or "{}")
                    route.fulfill(
                        status=200,
                        content_type="application/json",
                        body=json.dumps(
                            {
                                "job_id": "live-job",
                                "status": "queued",
                                "created_at": "2026-05-25T00:00:00Z",
                                "updated_at": "2026-05-25T00:00:00Z",
                                "result": None,
                                "error": None,
                                "progress": None,
                            }
                        ),
                    )

                def job_route(route: Any) -> None:
                    if live_job_status["value"] == "succeeded":
                        payload = {
                            "job_id": "live-job",
                            "status": "succeeded",
                            "created_at": "2026-05-25T00:00:00Z",
                            "updated_at": "2026-05-25T00:00:01Z",
                            "result": {"sources": {}},
                            "error": None,
                            "progress": {
                                "phase": "succeeded",
                                "message": "GBM training complete",
                                "iteration": 2,
                                "total_iterations": 10,
                                "percent": 100,
                                "metric": "gamma",
                                "latest": [{"dataset": "test", "metric": "gamma", "value": 7.2}],
                                "evaluation": {"training": {"gamma": [7.4, 7.3]}, "test": {"gamma": [7.35, 7.2]}},
                            },
                        }
                    elif live_job_status["value"] == "failed":
                        payload = {
                            "job_id": "live-job",
                            "status": "failed",
                            "created_at": "2026-05-25T00:00:00Z",
                            "updated_at": "2026-05-25T00:00:01Z",
                            "result": None,
                            "error": "Synthetic GBM training failure",
                            "progress": {
                                "phase": "failed",
                                "message": "Synthetic GBM training failure",
                            },
                        }
                    else:
                        progress_phase = (
                            live_job_status["value"]
                            if live_job_status["value"] in {"scoring", "shap", "artifacts"}
                            else "training"
                        )
                        progress_message = {
                            "scoring": "best iteration 2, scoring...",
                            "shap": "best iteration 2, SHAP values...",
                            "artifacts": "best iteration 2, tree artifacts...",
                        }.get(progress_phase, "training, tree 2/10, test gamma 7.2")
                        payload = {
                            "job_id": "live-job",
                            "status": "running",
                            "created_at": "2026-05-25T00:00:00Z",
                            "updated_at": "2026-05-25T00:00:01Z",
                            "result": None,
                            "error": None,
                            "progress": {
                                "phase": progress_phase,
                                "message": progress_message,
                                "iteration": 2,
                                "total_iterations": 10,
                                "percent": 18,
                                "metric": "gamma",
                                "grid_model_number": 1,
                                "grid_model_count": 25,
                                "latest": [{"dataset": "test", "metric": "gamma", "value": 7.2}],
                                "evaluation": {"training": {"gamma": [7.4, 7.3]}, "test": {"gamma": [7.35, 7.2]}},
                            },
                        }
                    route.fulfill(status=200, content_type="application/json", body=json.dumps(payload))

